package com.receiptledger.v1.persistence;

import android.content.*;import android.database.*;import android.database.sqlite.*;import com.receiptledger.v1.item.*;import com.receiptledger.v1.validation.*;import java.util.*;

public final class SqliteReceiptStore extends SQLiteOpenHelper implements ReceiptStore {
    public SqliteReceiptStore(Context context){super(context,ReceiptSchema.DB_NAME,null,ReceiptSchema.VERSION);}
    @Override public void onConfigure(SQLiteDatabase db){super.onConfigure(db);db.setForeignKeyConstraintsEnabled(true);}
    @Override public void onCreate(SQLiteDatabase db){db.execSQL(ReceiptSchema.CREATE_RECEIPTS);db.execSQL(ReceiptSchema.CREATE_ITEMS);db.execSQL(ReceiptSchema.CREATE_ISSUES);db.execSQL(ReceiptSchema.CREATE_RECEIPT_DATE_INDEX);}
    @Override public void onUpgrade(SQLiteDatabase db,int oldVersion,int newVersion){throw new IllegalStateException("Explicit DB migration required: "+oldVersion+" -> "+newVersion);}
    @Override public void save(ReceiptRecord r){if(r==null)throw new IllegalArgumentException("record");SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{ContentValues v=receiptValues(r);db.insertWithOnConflict("receipts",null,v,SQLiteDatabase.CONFLICT_REPLACE);db.delete("receipt_items","receipt_id=?",new String[]{r.id});db.delete("receipt_issues","receipt_id=?",new String[]{r.id});for(PersistedItem item:r.items)db.insertOrThrow("receipt_items",null,itemValues(r.id,item));for(int i=0;i<r.issues.size();i++){ContentValues iv=new ContentValues();iv.put("receipt_id",r.id);iv.put("ordinal",i);iv.put("issue",r.issues.get(i));db.insertOrThrow("receipt_issues",null,iv);}db.setTransactionSuccessful();}finally{db.endTransaction();}}
    @Override public ReceiptRecord get(String id){SQLiteDatabase db=getReadableDatabase();try(Cursor c=db.query("receipts",null,"id=?",new String[]{id},null,null,null)){return c.moveToFirst()?readRecord(db,c):null;}}
    @Override public List<ReceiptRecord> listNewestFirst(int limit){if(limit<1)return Collections.emptyList();limit=Math.min(limit,500);SQLiteDatabase db=getReadableDatabase();List<ReceiptRecord> out=new ArrayList<>();try(Cursor c=db.query("receipts",null,null,null,null,null,"created_at_ms DESC,id DESC",Integer.toString(limit))){while(c.moveToNext())out.add(readRecord(db,c));}return Collections.unmodifiableList(out);}
    @Override public int count(){return (int)DatabaseUtils.queryNumEntries(getReadableDatabase(),"receipts");}
    @Override public boolean delete(String id){return getWritableDatabase().delete("receipts","id=?",new String[]{id})>0;}
    private static ContentValues receiptValues(ReceiptRecord r){ContentValues v=new ContentValues();v.put("id",r.id);v.put("created_at_ms",r.createdAtMillis);put(v,"purchase_date",r.purchaseDate);put(v,"store_name",r.storeName);v.put("raw_ocr_text",r.rawOcrText);put(v,"printed_total",r.printedTotal);put(v,"item_line_sum",r.itemLineSum);put(v,"discount_sum",r.discountSum);put(v,"computed_net",r.computedNet);put(v,"difference",r.difference);v.put("validation_status",r.validationStatus.name());v.put("source_width",r.sourceWidth);v.put("source_height",r.sourceHeight);v.put("perspective_corrected",r.perspectiveCorrected?1:0);return v;}
    private static ContentValues itemValues(String receiptId,PersistedItem i){ContentValues v=new ContentValues();v.put("receipt_id",receiptId);v.put("ordinal",i.ordinal);v.put("row_index",i.rowIndex);v.put("name",i.name);put(v,"quantity",i.quantity);put(v,"unit_price",i.unitPrice);put(v,"line_amount",i.lineAmount);v.put("quantity_origin",i.quantityOrigin.name());v.put("unit_price_origin",i.unitPriceOrigin.name());v.put("line_amount_origin",i.lineAmountOrigin.name());v.put("resolution",i.resolution.name());put(v,"reason",i.reason);return v;}
    private ReceiptRecord readRecord(SQLiteDatabase db,Cursor c){String id=s(c,"id");List<PersistedItem> items=new ArrayList<>();try(Cursor x=db.query("receipt_items",null,"receipt_id=?",new String[]{id},null,null,"ordinal ASC")){while(x.moveToNext())items.add(new PersistedItem(x.getInt(x.getColumnIndexOrThrow("ordinal")),x.getInt(x.getColumnIndexOrThrow("row_index")),s(x,"name"),ni(x,"quantity"),nl(x,"unit_price"),nl(x,"line_amount"),origin(s(x,"quantity_origin")),origin(s(x,"unit_price_origin")),origin(s(x,"line_amount_origin")),resolution(s(x,"resolution")),ns(x,"reason")));}List<String> issues=new ArrayList<>();try(Cursor x=db.query("receipt_issues",new String[]{"issue"},"receipt_id=?",new String[]{id},null,null,"ordinal ASC")){while(x.moveToNext())issues.add(x.getString(0));}return new ReceiptRecord(id,c.getLong(c.getColumnIndexOrThrow("created_at_ms")),ns(c,"purchase_date"),ns(c,"store_name"),s(c,"raw_ocr_text"),nl(c,"printed_total"),nl(c,"item_line_sum"),nl(c,"discount_sum"),nl(c,"computed_net"),nl(c,"difference"),validation(s(c,"validation_status")),c.getInt(c.getColumnIndexOrThrow("source_width")),c.getInt(c.getColumnIndexOrThrow("source_height")),c.getInt(c.getColumnIndexOrThrow("perspective_corrected"))!=0,issues,items);}
    private static void put(ContentValues v,String key,String value){if(value==null)v.putNull(key);else v.put(key,value);}private static void put(ContentValues v,String key,Long value){if(value==null)v.putNull(key);else v.put(key,value);}private static void put(ContentValues v,String key,Integer value){if(value==null)v.putNull(key);else v.put(key,value);}private static String s(Cursor c,String n){return c.getString(c.getColumnIndexOrThrow(n));}private static String ns(Cursor c,String n){int i=c.getColumnIndexOrThrow(n);return c.isNull(i)?null:c.getString(i);}private static Long nl(Cursor c,String n){int i=c.getColumnIndexOrThrow(n);return c.isNull(i)?null:c.getLong(i);}private static Integer ni(Cursor c,String n){int i=c.getColumnIndexOrThrow(n);return c.isNull(i)?null:c.getInt(i);}private static ValueOrigin origin(String s){try{return ValueOrigin.valueOf(s);}catch(Exception e){return ValueOrigin.UNKNOWN;}}private static ItemResolution resolution(String s){try{return ItemResolution.valueOf(s);}catch(Exception e){return ItemResolution.PARTIAL;}}private static ValidationStatus validation(String s){try{return ValidationStatus.valueOf(s);}catch(Exception e){return ValidationStatus.INCOMPLETE;}}
}
